-- WONY fresh database schema for Supabase
create extension if not exists pgcrypto;
create type public.user_role as enum ('player','moderator','admin','owner');
create type public.order_status as enum ('pending','paid','approved','rejected','cancelled','delivered');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, username text unique not null check (username ~ '^[a-z0-9_]{3,20}$'), display_name text, growid text unique, whatsapp text, role public.user_role not null default 'player', coins bigint not null default 0 check(coins>=0), xp bigint not null default 0 check(xp>=0), level int not null default 1, verified boolean not null default false, banned boolean not null default false, ban_reason text, show_leaderboard boolean not null default true, avatar_url text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.items (id bigint generated by default as identity primary key, game_item_id int unique, name text not null, slug text unique not null, rarity text not null default 'common', image_url text, tradable boolean not null default true, active boolean not null default true, created_at timestamptz default now());
create table public.inventory (id bigint generated by default as identity primary key, user_id uuid references public.profiles(id) on delete cascade not null, item_id bigint references public.items(id) not null, quantity int not null default 1 check(quantity>=0), locked_quantity int not null default 0 check(locked_quantity>=0), updated_at timestamptz default now(), unique(user_id,item_id));
create table public.coin_ledger (id bigint generated by default as identity primary key, user_id uuid references public.profiles(id) not null, amount bigint not null, balance_after bigint not null, kind text not null, reference_id text, note text, created_at timestamptz default now());
create table public.market_listings (id bigint generated by default as identity primary key, seller_id uuid references public.profiles(id) not null, item_id bigint references public.items(id) not null, quantity int not null check(quantity>0), remaining int not null check(remaining>=0), price_per_item bigint not null check(price_per_item>0), status text not null default 'open', created_at timestamptz default now(), updated_at timestamptz default now());
create table public.market_transactions (id bigint generated by default as identity primary key, listing_id bigint references public.market_listings(id) not null, buyer_id uuid references public.profiles(id) not null, seller_id uuid references public.profiles(id) not null, quantity int not null, total bigint not null, tax bigint not null default 0, created_at timestamptz default now());
create table public.topup_orders (id uuid primary key default gen_random_uuid(), user_id uuid references public.profiles(id) not null, coins bigint not null, amount_idr bigint not null, payment_method text default 'qris', payment_reference text, proof_url text, status public.order_status not null default 'pending', created_at timestamptz default now(), updated_at timestamptz default now());
create table public.quests (id bigint generated by default as identity primary key, title text not null, description text, kind text not null, target int not null default 1, reward_coins bigint not null default 0, reward_xp bigint not null default 0, starts_at timestamptz, ends_at timestamptz, active boolean default true);
create table public.quest_progress (quest_id bigint references public.quests(id) on delete cascade, user_id uuid references public.profiles(id) on delete cascade, progress int not null default 0, claimed boolean not null default false, updated_at timestamptz default now(), primary key(quest_id,user_id));
create table public.events (id bigint generated by default as identity primary key, title text not null, description text, banner_url text, starts_at timestamptz not null, ends_at timestamptz not null, active boolean default true);
create table public.redeem_codes (id bigint generated by default as identity primary key, code text unique not null, reward_coins bigint default 0, reward_item_id bigint references public.items(id), reward_quantity int default 0, max_uses int default 1, used_count int default 0, expires_at timestamptz, active boolean default true);
create table public.redeem_claims (code_id bigint references public.redeem_codes(id), user_id uuid references public.profiles(id), claimed_at timestamptz default now(), primary key(code_id,user_id));
create table public.notifications (id bigint generated by default as identity primary key, user_id uuid references public.profiles(id) on delete cascade, title text not null, body text, kind text default 'info', read_at timestamptz, created_at timestamptz default now());
create table public.plant_trees (user_id uuid primary key references public.profiles(id) on delete cascade, stage int not null default 1, water_count int not null default 0, health int not null default 100, planted_at timestamptz default now(), harvest_at timestamptz, updated_at timestamptz default now());
create table public.shop_products (id bigint generated by default as identity primary key, kind text not null check(kind in ('role','asset')), name text not null, description text, price_idr bigint default 0, price_coins bigint default 0, stock int, active boolean default true, image_url text);
create table public.shop_orders (id uuid primary key default gen_random_uuid(), user_id uuid references public.profiles(id) not null, product_id bigint references public.shop_products(id) not null, quantity int default 1, total_idr bigint default 0, total_coins bigint default 0, status public.order_status default 'pending', notes text, created_at timestamptz default now());
create table public.app_settings (key text primary key, value jsonb not null, updated_at timestamptz default now());
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,username,display_name) values(new.id,coalesce(new.raw_user_meta_data->>'username',split_part(new.email,'@',1)),coalesce(new.raw_user_meta_data->>'username',split_part(new.email,'@',1))); return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
alter table public.profiles enable row level security; alter table public.inventory enable row level security; alter table public.coin_ledger enable row level security; alter table public.market_listings enable row level security; alter table public.market_transactions enable row level security; alter table public.topup_orders enable row level security; alter table public.quest_progress enable row level security; alter table public.notifications enable row level security; alter table public.plant_trees enable row level security; alter table public.shop_orders enable row level security;
create policy "profiles public read" on public.profiles for select using (true); create policy "profile self update" on public.profiles for update using(auth.uid()=id);
create policy "inventory self read" on public.inventory for select using(auth.uid()=user_id); create policy "ledger self read" on public.coin_ledger for select using(auth.uid()=user_id); create policy "listing public read" on public.market_listings for select using(true); create policy "listing self insert" on public.market_listings for insert with check(auth.uid()=seller_id); create policy "listing self update" on public.market_listings for update using(auth.uid()=seller_id);
create policy "market transaction party read" on public.market_transactions for select using(auth.uid()=buyer_id or auth.uid()=seller_id); create policy "topup self read" on public.topup_orders for select using(auth.uid()=user_id); create policy "topup self insert" on public.topup_orders for insert with check(auth.uid()=user_id); create policy "quest progress self read" on public.quest_progress for select using(auth.uid()=user_id); create policy "notification self" on public.notifications for select using(auth.uid()=user_id); create policy "plant self" on public.plant_trees for select using(auth.uid()=user_id); create policy "shop order self" on public.shop_orders for select using(auth.uid()=user_id);
insert into public.app_settings(key,value) values ('site', '{"name":"WONY","maintenance":false,"language":"id"}'),('economy','{"marketTaxPercent":5,"dailyReward":40,"topupRate":100}');
